struct vdi_fixture{uint16_t opcode;int calls;}; struct line_fixture{int calls;int16_t x1,y1,x2,y2;uint16_t color,style;};
static int32_t vd(void*o,uint16_t op,const int16_t*i,uint16_t ni,const int16_t*p,uint16_t np,int16_t*out,uint16_t oc,uint16_t*no,int16_t*po,uint16_t pc,uint16_t*npo){struct vdi_fixture*f=o;(void)i;(void)ni;(void)p;(void)np;(void)oc;(void)pc;f->opcode=op;++f->calls;out[0]=42;po[0]=320;po[1]=200;*no=1;*npo=2;return 0;}
static int line(void*o,int16_t x1,int16_t y1,int16_t x2,int16_t y2,uint16_t color,uint16_t style){struct line_fixture*f=o;++f->calls;f->x1=x1;f->y1=y1;f->x2=x2;f->y2=y2;f->color=color;f->style=style;return 0;}
int main(void){struct amtari_context c={0};struct vdi_fixture v={0};struct line_fixture l={0};int16_t out[8]={0},po[8]={0},p[6]={10,20,30,40,50,60},in[1];uint16_t no=0,npo=0;assert(amtari_init(&c)==0);assert(amtari_vdi_configure(&c,640,400,16)==0);assert(amtari_vdi_dispatch(&c,1,0,0,0,0,out,8,&no,po,8,&npo)==0);assert(no==3&&npo==2&&out[0]==1&&po[0]==639&&po[1]==399);assert(amtari_vdi_line_bind(&c,line,&l)==0);in[0]=3;assert(amtari_vdi_dispatch(&c,15,in,1,0,0,out,8,&no,po,8,&npo)==0);assert(no==1&&out[0]==3);in[0]=5;assert(amtari_vdi_dispatch(&c,17,in,1,0,0,out,8,&no,po,8,&npo)==0);assert(no==1&&out[0]==5);assert(amtari_vdi_dispatch(&c,6,0,0,p,6,out,8,&no,po,8,&npo)==0);assert(l.calls==2);assert(l.x1==30&&l.y1==40&&l.x2==50&&l.y2==60&&l.style==3&&l.color==5);in[0]=99;assert(amtari_vdi_dispatch(&c,15,in,1,0,0,out,8,&no,po,8,&npo)==0);assert(out[0]==1);in[0]=99;assert(amtari_vdi_dispatch(&c,17,in,1,0,0,out,8,&no,po,8,&npo)==0);assert(out[0]==1);assert(amtari_vdi_bind(&c,vd,&v)==0);assert(amtari_vdi_dispatch(&c,100,0,0,0,0,out,8,&no,po,8,&npo)==0);assert(v.calls==1&&v.opcode==100);return 0;}
